window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-47280754ea2f9b52"]={"versions": [{"id": "FIG-47280754ea2f9b52", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Classic Platform (Software Component Template). Das Diagramm spezifiziert die semantische Modellierung primitiver Datentypen (<code>PrimitiveType</code>) innerhalb des AUTOSAR-Metamodells über die Anbindung von Software-Datendefinitionseigenschaften (<code>SwDataDefProps</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>Datatype</code>: Abstrakte Basisklasse, spezialisiert als <code>ARElement</code> mit dem Stereotyp <code>«atpType»</code>.</li>\n<li><code>PrimitiveType</code>: Abstrakter primitiver Datentyp mit dem Stereotyp <code>«atpType»</code>, erbt von <code>Datatype</code>.</li>\n<li>Spezialisierungen von <code>PrimitiveType</code>:</li>\n<li><code>IntegerType</code> (mit Spezialisierung/Stereotyp <code>Range</code>)</li>\n<li><code>RealType</code> (mit Spezialisierung/Stereotyp <code>Range</code>)</li>\n<li><code>StringType</code></li>\n<li><code>CharType</code></li>\n<li><code>OpaqueType</code></li>\n<li><code>BooleanType</code></li>\n<li><code>SwDataDefProps</code>: Eigenschaftscontainer (annotiert mit <code>IsSyscond</code>), per Komposition (<code>+swDataDefProps</code>, Multiplizität <code>0..1</code>) an <code>PrimitiveType</code> angebunden.</li>\n<li><code>CompuMethod</code>: Als <code>ARElement</code> typisiert, per Assoziation (<code>+compuMethod</code>, Multiplizität <code>0..1</code>) von <code>SwDataDefProps</code> referenziert.</li>\n<li><code>PrimitiveSpecification</code>: Spezialisierung von <code>ValueSpecification</code>, per Komposition (<code>+invalidValue</code>, Multiplizität <code>0..1</code>) in <code>SwDataDefProps</code> eingebunden zur Festlegung eines Ungültigkeitswerts.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Laufzeitinteraktionen. Das Diagramm definiert strukturelle Typisierungs- und Konfigurationsbeziehungen zur Entwurfs- und Generierungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konfigurations- und Modellierungsrichtlinie für primitive Datentypen in Software-Komponentenbeschreibungen. Semantische Eigenschaften wie Rechenmethoden (<code>CompuMethod</code>) zur physikalischen Skalierung und Grenzwerte bzw. Ersatzwerte (<code>invalidValue</code>) werden zentral über <code>SwDataDefProps</code> am primitiven Datentyp hinterlegt. Die Multiplizitäten <code>0..1</code> weisen darauf hin, dass diese Angaben optional sind.</p>"}, {"id": "FIG-351332befa37ef8e", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Classic Platform (Software Component Template). Das Diagramm spezifiziert die semantische Modellierung primitiver Datentypen (<code>PrimitiveType</code>) innerhalb des AUTOSAR-Metamodells über die Anbindung von Software-Datendefinitionseigenschaften (<code>SwDataDefProps</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>Datatype</code>: Abstrakte Basisklasse, spezialisiert als <code>ARElement</code> mit dem Stereotyp <code>«atpType»</code>.</li>\n<li><code>PrimitiveType</code>: Abstrakter primitiver Datentyp mit dem Stereotyp <code>«atpType»</code>, erbt von <code>Datatype</code>.</li>\n<li>Spezialisierungen von <code>PrimitiveType</code>:</li>\n<li><code>IntegerType</code> (mit Spezialisierung/Stereotyp <code>Range</code>)</li>\n<li><code>RealType</code> (mit Spezialisierung/Stereotyp <code>Range</code>)</li>\n<li><code>StringType</code></li>\n<li><code>CharType</code></li>\n<li><code>OpaqueType</code></li>\n<li><code>BooleanType</code></li>\n<li><code>SwDataDefProps</code>: Eigenschaftscontainer (annotiert mit <code>IsSyscond</code>), per Komposition (<code>+swDataDefProps</code>, Multiplizität <code>0..1</code>) an <code>PrimitiveType</code> angebunden.</li>\n<li><code>CompuMethod</code>: Als <code>ARElement</code> typisiert, per Assoziation (<code>+compuMethod</code>, Multiplizität <code>0..1</code>) von <code>SwDataDefProps</code> referenziert.</li>\n<li><code>PrimitiveSpecification</code>: Spezialisierung von <code>ValueSpecification</code>, per Komposition (<code>+invalidValue</code>, Multiplizität <code>0..1</code>) in <code>SwDataDefProps</code> eingebunden zur Festlegung eines Ungültigkeitswerts.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Laufzeitinteraktionen. Das Diagramm definiert strukturelle Typisierungs- und Konfigurationsbeziehungen zur Entwurfs- und Generierungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konfigurations- und Modellierungsrichtlinie für primitive Datentypen in Software-Komponentenbeschreibungen. Semantische Eigenschaften wie Rechenmethoden (<code>CompuMethod</code>) zur physikalischen Skalierung und Grenzwerte bzw. Ersatzwerte (<code>invalidValue</code>) werden zentral über <code>SwDataDefProps</code> am primitiven Datentyp hinterlegt. Die Multiplizitäten <code>0..1</code> weisen darauf hin, dass diese Angaben optional sind.</p>"}], "trans": [{"from": "FIG-47280754ea2f9b52", "to": "FIG-351332befa37ef8e", "fr": "R3.0.7", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
